// === RSS-ленты разделены на категории ===
const internationalFeeds = [
  'https://www.finam.ru/international/advanced/rsspoint/',
  'https://www.coindesk.com/arc/outboundfeeds/rss/',
  'https://www.investing.com/rss/news_25.rss',
  'https://www.investing.com/rss/news_14.rss',
  'https://www.investing.com/rss/news_1.rss',
];

const russiaFeeds = [
  // Финам — аналитика рынков и компаний (чисто финансовые)
  'https://www.finam.ru/analysis/marketnews/rsspoint/',
  'https://www.finam.ru/analysis/conews/rsspoint/',
  'https://www.finam.ru/analysis/forecasts/rsspoint/',
  // РБК — только раздел Финансы (ID=5) и Инвестиции
  'https://rssexport.rbc.ru/rbcnews/news/5/full.rss',
  // SmartLab — трейдерский контент
  'https://smart-lab.ru/rss/flow/',
  // БКС Экспресс — брокерская аналитика
  'https://bcs-express.ru/rss',
];

const allTitles = [];
const seenNormalized = new Set();

// Нормализация для дедупликации
function normalize(title) {
  return title.toLowerCase().replace(/[^a-zа-яё0-9\s]/gi, '').replace(/\s+/g, ' ').trim();
}

// Извлечение ключевых слов (убираем стоп-слова)
const ruStopWords = new Set(['и','в','на','по','за','из','от','до','для','что','как','это','при','его','она','они','все','уже','или','так','но','не','с','к','о','а','у','со','ко','бы','же','ли','то','да','нет','был','была','были','будет','может','более','между','после','перед','через','также','который','которая','которое','которые','этот','эта','эти','свой','свои','около','против','вместе','кроме','только','очень','этого','этой','этих','того','тому','всех','всей','одна','одно','одни','другие','каждый','любой','много','мало','пока','если']);

function getKeywords(normalized) {
  return normalized.split(' ').filter(w => w.length > 2 && !ruStopWords.has(w));
}

// Проверка похожести — строгая дедупликация
function isSimilar(normA, normB) {
  if (normA === normB) return true;
  if (normA.includes(normB) || normB.includes(normA)) return true;

  const kwA = getKeywords(normA);
  const kwB = getKeywords(normB);
  if (kwA.length === 0 || kwB.length === 0) return false;

  const setB = new Set(kwB);
  const common = kwA.filter(w => setB.has(w)).length;

  const ratioA = common / kwA.length;
  const ratioB = common / kwB.length;
  if (ratioA > 0.35 || ratioB > 0.35) return true;

  const longA = kwA.filter(w => w.length > 4);
  const longB = new Set(kwB.filter(w => w.length > 4));
  if (longA.length > 0 && longB.size > 0) {
    const longCommon = longA.filter(w => longB.has(w)).length;
    if (longCommon >= 1) return true;
  }

  return false;
}

// Список слов-стоп для фильтрации служебных заголовков фида
const stopWords = [
  'finam.ru', 'investing.com', 'coindesk', 'рбк', 'rbc.ru',
  'smartlab', 'smart-lab', 'bcs express', 'бкс экспресс',
  'интерфакс', 'interfax', 'новости и аналитика',
  'новости дня', 'все новости', 'лента новостей',
];

function isServiceTitle(title) {
  const low = title.toLowerCase();
  return stopWords.some(sw => low.includes(sw)) || title.length < 12;
}

// Фильтр политических новостей — пропускаем только финансы/рынки
const politicalWords = [
  'путин', 'зеленск', 'байден', 'трамп', 'навальн', 'лавров', 'шойгу',
  'песков', 'мишустин', 'депутат', 'госдума', 'дума', 'парламент',
  'кремль', 'белый дом', 'пентагон', 'нато', 'nato', 'оон',
  'мид ', 'минобороны', 'генштаб', 'военн', 'армия', 'войск',
  'ракет', 'удар', 'обстрел', 'фронт', 'наступлен', 'оборон',
  'сво ', 'мобилизац', 'призыв', 'повестк',
  'санкци', 'выбор', 'голосован', 'партия', 'единая россия',
  'оппозиц', 'протест', 'митинг', 'задержан', 'арест',
  'приговор', 'суд над', 'уголовн', 'следствие', 'обыск',
  'террор', 'взрыв', 'теракт', 'беженц', 'миграц',
  'донбасс', 'крым', 'херсон', 'запорож', 'луганск', 'донецк',
  'переговор', 'перемири', 'капитуляц', 'конфликт',
];

function isPolitical(title) {
  const low = title.toLowerCase();
  return politicalWords.some(pw => low.includes(pw));
}

// Извлечение заголовков только из <item> блоков
function extractItemTitles(xml, maxCount) {
  const titles = [];
  const itemRegex = /<item[\s>]([\s\S]*?)<\/item>/gi;
  let itemMatch;

  while ((itemMatch = itemRegex.exec(xml)) !== null && titles.length < maxCount) {
    const itemContent = itemMatch[1];
    const titleMatch = itemContent.match(/<title><!\[CDATA\[(.*?)\]\]>|<title>(.*?)<\/title>/);
    if (titleMatch) {
      const title = (titleMatch[1] || titleMatch[2] || '').trim();
      if (title && !isServiceTitle(title) && !isPolitical(title)) {
        titles.push(title);
      }
    }
  }

  if (titles.length === 0) {
    const entryRegex = /<entry[\s>]([\s\S]*?)<\/entry>/gi;
    let entryMatch;
    while ((entryMatch = entryRegex.exec(xml)) !== null && titles.length < maxCount) {
      const entryContent = entryMatch[1];
      const titleMatch = entryContent.match(/<title[^>]*><!\[CDATA\[(.*?)\]\]>|<title[^>]*>(.*?)<\/title>/);
      if (titleMatch) {
        const title = (titleMatch[1] || titleMatch[2] || '').trim();
        if (title && !isServiceTitle(title) && !isPolitical(title)) {
          titles.push(title);
        }
      }
    }
  }

  return titles;
}

// Добавление заголовков с дедупликацией
function addTitles(titles) {
  for (const title of titles) {
    const norm = normalize(title);
    let isDuplicate = false;
    for (const seen of seenNormalized) {
      if (isSimilar(norm, seen)) {
        isDuplicate = true;
        break;
      }
    }
    if (!isDuplicate) {
      seenNormalized.add(norm);
      allTitles.push(title);
    }
  }
}

// Загрузка фидов с User-Agent и таймаутом
async function fetchFeed(feedUrl, maxTitles) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: feedUrl,
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Accept': 'application/rss+xml, application/xml, text/xml, */*',
      },
      returnFullResponse: false,
      timeout: 15000,
    });
    return extractItemTitles(response, maxTitles);
  } catch (e) {
    console.log('Feed error: ' + feedUrl + ' - ' + e.message);
    return [];
  }
}

// Загружаем международные ленты (по 5 заголовков)
for (const feedUrl of internationalFeeds) {
  const titles = await fetchFeed.call(this, feedUrl, 5);
  addTitles(titles);
}

// Загружаем российские ленты (по 7 заголовков)
for (const feedUrl of russiaFeeds) {
  const titles = await fetchFeed.call(this, feedUrl, 7);
  addTitles(titles);
}

const newsList = allTitles.map((t, i) => `${i + 1}. ${t}`).join(' | ');

// ========== ИМЯ ВЕДУЩЕЙ — менять только здесь ==========
const HOST_NAME = 'Мария Новикова';
const SIGNOFF_TEXT = 'С вами была ' + HOST_NAME + ', Держитесь верного курса.';

const prompt = 'Ты профессиональная радиоведущая по имени ' + HOST_NAME + ' — харизматичная, остроумная, с фирменным сухим юмором. Составь выпуск деловых радионовостей из следующих новостей. Переведи на русский язык и перепиши в стиле делового радиорепортажа. ВАЖНО: это ФИНАНСОВЫЙ выпуск. Говори ТОЛЬКО о рынках, акциях, валютах, сырье, экономических показателях, компаниях, сделках. НЕ упоминай политику, военные действия, санкции, политиков, геополитику. НИКОГДА не повторяй одну и ту же тему дважды. Если несколько новостей об одном — объедини в один комментарий. ВАЖНО: никогда не используй приветствия привязанные к времени суток. Используй только нейтральные: Приветствую вас, С вами ' + HOST_NAME + ', Рада быть с вами. Структура строго по блокам: 1) Мировая экономика, 2) Мировые рынки, 3) Фондовый рынок США, 4) Крипторынок, 5) Фондовый рынок РФ. Блок РФ самый подробный. Если по блоку нет новостей — пропусти. СТИЛЬ РАДИО-ВЕДУЩЕЙ ДЛЯ TTS: пиши короткими энергичными предложениями по 8-15 слов. Длинное предложение разбивай точкой на два. Используй тире между смысловыми частями для создания драматической паузы. Перед ключевыми цифрами и названиями компаний ставь запятую. Между блоками новостей используй фразы-переходы вроде: А теперь, Переходим к, Что касается, Тем временем. Задавай риторические вопросы — они оживляют речь. Все числа пиши словами: не 15% а пятнадцать процентов, не $100 а сто долларов. Тикеры раскрывай: не AAPL а Apple, не GAZP а Газпром. Добавляй уместные ироничные замечания. СТРОГО ВАЖНО: объём от 2500 до 3000 символов, не превышай 3500. Только текст сплошным потоком без абзацев. Не используй звёздочки, кавычки, скобки, нумерацию, маркеры списков, спецсимволы. Разрешены только: буквы, цифры, запятые, точки, тире, вопросительные и восклицательные знаки. Начинай сразу с приветствия. Твоё имя ' + HOST_NAME + ' и никак иначе. В конце скажи: ' + SIGNOFF_TEXT + ' Новости: ' + newsList;

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.deepseek.com/chat/completions',
  headers: {
    'Authorization': 'Bearer YOUR_API_KEY',
    'Content-Type': 'application/json'
  },
  body: {
    model: 'deepseek-chat',
    messages: [
      { role: 'system', content: 'Ты генератор текста для голосового синтеза OpenAI TTS. Тебя зовут ' + HOST_NAME + '. Никогда не называй себя другим именем. Отвечай ТОЛЬКО текстом радиовыпуска. Без вводных фраз, без пояснений, без мета-комментариев, без markdown. Первое слово ответа должно быть приветствием. Каждая новость уникальна — никаких повторов. ПРАВИЛА СТИЛЯ ДЛЯ TTS: пиши короткими предложениями по 8-15 слов. Используй запятые для коротких пауз и точки для длинных. Перед важными цифрами и названиями ставь запятую — это создаёт акцент. Между блоками новостей делай переход через фразу-мостик. Все числа пиши словами: не 15% а пятнадцать процентов, не $100 а сто долларов, не 3.5 а три с половиной. Аббревиатуры раскрывай при первом упоминании. Ставь тире между смысловыми частями для драматической паузы. Риторические вопросы создают интонацию — используй их. Восклицания для акцента, но не больше двух на весь выпуск.' },
      { role: 'user', content: prompt }
    ],
    max_tokens: 1800
  },
  json: true
});

// =============== ОЧИСТКА ТЕКСТА ===============

let text = response.choices[0].message.content;

// DEBUG: логируем начало сырого текста (первые 100 символов + их коды)
const rawStart = text.substring(0, 100);
const rawCodes = [...rawStart].map(c => c.charCodeAt(0)).join(',');
console.log('RAW TEXT START: ' + rawStart);
console.log('RAW CHAR CODES: ' + rawCodes);

// 1. Удаляем невидимые Unicode-символы
text = text.replace(/[\uFEFF\u200B\u200C\u200D\u200E\u200F\u2028\u2029\u202A-\u202E\u2060\u2066-\u2069\uFFF9-\uFFFC]/g, '');
text = text.replace(/[\x00-\x09\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, '');

// 2. Удаляем markdown и визуальные спецсимволы (НО сохраняем TTS-пунктуацию: . , ! ? -)
text = text.replace(/\\n/g, ' ');
text = text.replace(/\n/g, ' ');
text = text.replace(/\r/g, ' ');
text = text.replace(/\t/g, ' ');
// Убираем только визуальный мусор, сохраняем . , ! ? - для TTS
text = text.replace(/[*#\[\](){}«»""„"''`~^|\\/<>@&=+$€£¥§©®™•°±×÷―…]/g, '');

// 3. Нормализуем тире: em-dash и en-dash → обычное тире с пробелами (TTS читает как паузу)
text = text.replace(/[—–]/g, ' - ');

// 4. Удаляем эмодзи
text = text.replace(/[\u{1F000}-\u{1FFFF}]/gu, '');
text = text.replace(/[\u{2600}-\u{27BF}]/gu, '');

// 5. Нормализуем пробелы
text = text.replace(/\s+/g, ' ');
text = text.trim();

// 5. Принудительно заменяем "Джой" на имя ведущей (страховка от LLM)
text = text.replace(/Джой/g, HOST_NAME);

// 6. Удаляем преамбулу — ищем первое приветствие
const greetings = [
  'Приветствую', 'С вами ' + HOST_NAME, 'Рада быть',
  'Здравствуйте', 'Привет', 'На связи ' + HOST_NAME,
  'Это ' + HOST_NAME, 'Снова с вами', 'Добро пожаловать',
  'Рада приветствовать', 'И снова', 'Вы слушаете', 'В эфире',
  'С вами Мария', 'На связи Мария',
];
for (const g of greetings) {
  const idx = text.indexOf(g);
  if (idx >= 0 && idx < 300) {
    text = text.substring(idx);
    break;
  }
}

// 7. АБСОЛЮТНАЯ ГАРАНТИЯ: убираем ВСЁ что стоит до первой кириллической буквы
// Это ловит любой мусор: невидимые символы, латиницу, цифры, пунктуацию
text = text.replace(/^[^А-ЯЁа-яё]+/, '');

// 8. Если текст начинается со строчной — ищём первую заглавную (начало предложения)
if (text.length > 0 && text[0].match(/[а-яё]/)) {
  const upperMatch = text.match(/[А-ЯЁ]/);
  if (upperMatch) {
    const idx = text.indexOf(upperMatch[0]);
    if (idx > 0 && idx < 200) {
      text = text.substring(idx);
    }
  }
}

// DEBUG: логируем начало очищенного текста
console.log('CLEAN TEXT START: ' + text.substring(0, 100));
console.log('CLEAN FIRST CHAR CODE: ' + text.charCodeAt(0));
console.log('CLEAN TEXT LENGTH: ' + text.length);

// =============== TTS POST-PROCESSING (радио-голос) ===============

// 1. Раскрываем оставшиеся числа в словесную форму (DeepSeek может пропустить)
const numberWords = {
  '0': 'ноль', '1': 'один', '2': 'два', '3': 'три', '4': 'четыре',
  '5': 'пять', '6': 'шесть', '7': 'семь', '8': 'восемь', '9': 'девять',
  '10': 'десять', '11': 'одиннадцать', '12': 'двенадцать',
  '13': 'тринадцать', '14': 'четырнадцать', '15': 'пятнадцать',
  '16': 'шестнадцать', '17': 'семнадцать', '18': 'восемнадцать',
  '19': 'девятнадцать', '20': 'двадцать', '30': 'тридцать',
  '40': 'сорок', '50': 'пятьдесят', '60': 'шестьдесят',
  '70': 'семьдесят', '80': 'восемьдесят', '90': 'девяносто',
  '100': 'сто', '200': 'двести', '300': 'триста',
  '500': 'пятьсот', '1000': 'тысяча',
};

// Раскрываем символы валют и процентов
text = text.replace(/\$/g, ' долларов ');
text = text.replace(/€/g, ' евро ');
text = text.replace(/£/g, ' фунтов ');
text = text.replace(/¥/g, ' йен ');
text = text.replace(/₽/g, ' рублей ');
text = text.replace(/%/g, ' процентов');

// Раскрываем простые числа (1-20) когда они стоят отдельно
text = text.replace(/\b(\d{1,4})\b/g, (match) => {
  return numberWords[match] || match;
});

// 2. Раскрываем популярные финансовые аббревиатуры
text = text.replace(/\bЦБ РФ\b/g, 'Центробанк');
text = text.replace(/\bЦБ\b/g, 'Центробанк');
text = text.replace(/\bФРС\b/g, 'Федрезерв');
text = text.replace(/\bЕЦБ\b/g, 'Европейский центробанк');
text = text.replace(/\bМВФ\b/g, 'Международный валютный фонд');
text = text.replace(/\bВВП\b/g, 'В В П');
text = text.replace(/\bIPO\b/gi, 'ай пи о');
text = text.replace(/\bETF\b/gi, 'и ти эф');
text = text.replace(/\bP\/E\b/gi, 'пи и');
text = text.replace(/\bS&P\b/gi, 'эс энд пи');
text = text.replace(/\bNASDAQ\b/gi, 'Насдак');
text = text.replace(/\bDow Jones\b/gi, 'Доу Джонс');
text = text.replace(/\bBTC\b/g, 'биткоин');
text = text.replace(/\bETH\b/g, 'эфириум');
text = text.replace(/\bМОЕКС\b/gi, 'Мосбиржа');
text = text.replace(/\bMOEX\b/gi, 'Мосбиржа');
text = text.replace(/\bРТС\b/g, 'эр тэ эс');

// 3. Фиксим пунктуацию для ритма
// Двойные точки/запятые
text = text.replace(/\.{2,}/g, '.');
text = text.replace(/,{2,}/g, ',');
// Пробел перед знаками пунктуации убираем
text = text.replace(/\s+([.,!?])/g, '$1');
// Пробел после знаков пунктуации добавляем
text = text.replace(/([.,!?])([А-ЯЁа-яё])/g, '$1 $2');
// Тире с пробелами для паузы
text = text.replace(/\s*-\s*/g, ' - ');
// Убираем тире в начале предложений (если осталось)
text = text.replace(/^\s*-\s*/, '');

// 4. Финальная нормализация пробелов
text = text.replace(/\s+/g, ' ');
text = text.trim();

// =============== ОБРЕЗКА ПОД ЛИМИТ TTS ===============

const TTS_LIMIT = 4090;
const SIGNOFF = ' ' + SIGNOFF_TEXT;
const SIGNOFF_MARKER = 'С вами была ' + HOST_NAME;

if (text.length > TTS_LIMIT) {
  const hasSignoff = text.indexOf(SIGNOFF_MARKER) !== -1 && text.indexOf(SIGNOFF_MARKER) < TTS_LIMIT;

  if (hasSignoff) {
    const signoffEnd = text.indexOf('верного курса.') + 'верного курса.'.length;
    if (signoffEnd > 0 && signoffEnd <= TTS_LIMIT) {
      text = text.substring(0, signoffEnd);
    } else {
      text = text.substring(0, TTS_LIMIT);
    }
  } else {
    const cutLimit = TTS_LIMIT - SIGNOFF.length;
    const trimmed = text.substring(0, cutLimit);
    const lastDot = trimmed.lastIndexOf('.');
    if (lastDot > cutLimit * 0.7) {
      text = trimmed.substring(0, lastDot + 1) + SIGNOFF;
    } else {
      text = trimmed + SIGNOFF;
    }
  }
}

// Гарантия: если концовка отсутствует и текст помещается — дописываем
if (!text.includes(SIGNOFF_MARKER) && (text.length + SIGNOFF.length) <= 4096) {
  text = text.replace(/\s*$/, '') + SIGNOFF;
}

response.choices[0].message.content = text;

return [{
  json: response
}];
